use super::*;
use photocraft_engine::doc::{Affine, AlphaChannel, BlendMode, Document, Layer, LayerMask, Metadata, PixelFormat, Rect, SampleType, Slice, SliceOrigin, SmartFilter};
use photocraft_raster::Surface;
use std::{io::Read, path::PathBuf, sync::atomic::{AtomicBool,Ordering}};

struct Directory(PathBuf);
impl Drop for Directory {fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
fn directory()->Directory{let path=std::env::temp_dir().join(format!("linked-copy-{}",ulid::Ulid::new()));std::fs::create_dir_all(&path).unwrap();Directory(path)}
fn rgba()->Vec<u8>{vec![255,0,0,255,0,255,0,255,0,0,255,255,255,255,255,255]}
fn encoded(format:&str,pixels:Vec<u8>)->Vec<u8>{match format{
    "png"=>{let image=photocraft_codecs::Image::from_u8(2,2,photocraft_codecs::ChannelLayout::Rgba,pixels).unwrap();photocraft_codecs::encode(&image,photocraft_codecs::Format::Png,&Default::default()).unwrap()},
    "psd"|"psb"=>{use photocraft_psd::{Compression,LayerSpec,PixelData,PsdBuilder,Version};let mut builder=PsdBuilder::new(2,2).version(if format=="psb"{Version::Psb}else{Version::Psd}).compression(Compression::Raw);builder.push_layer(LayerSpec::new("Known",0,0,2,2,PixelData::Rgba8(pixels.clone())));builder.composite(PixelData::Rgba8(pixels));builder.to_bytes().unwrap()},
    "pcraft"=>photocraft_engine::smart_cmds::encode_source(&photocraft_io::import("source.png",&encoded("png",pixels)).unwrap().document).unwrap(),_=>unreachable!()}}
fn object_layer(name:&str,source:SmartSource,x:i32,y:i32,format:PixelFormat)->Layer{
    let mut cache=Surface::new(format);cache.fill_rect(Rect::from_xywh(x,y,1,1),&[0.25,0.5,0.75,1.]);let mut object=SmartObject::new(source,Affine::translate(f64::from(x),f64::from(y)),Some(cache));object.smart_filters=vec![SmartFilter{command:"filter.cameraRaw".into(),params:json!({"exposure":2,"vendor":{"retain":[null,7]}}),visible:true,opacity:0.37,blend:BlendMode::Multiply},SmartFilter{command:"plugin.run".into(),params:json!({"path":"must not execute"}),visible:true,opacity:1.,blend:BlendMode::Normal}];let mut filter_mask=LayerMask::hide_all();filter_mask.enabled=false;filter_mask.linked=false;filter_mask.density=0.42;filter_mask.feather=1.25;object.filter_mask=Some(filter_mask);object.psd_raw=Some(Arc::new(b"retained placed data".to_vec()));let mut layer=Layer::new(name,LayerContent::Smart(object));layer.psd_id=Some(53);let mut mask=LayerMask::reveal_all();mask.linked=false;mask.density=0.6;layer.mask=Some(mask);for key in [*b"SoLd",*b"SoLE",*b"PlLd",*b"zzzz"]{layer.psd_blocks.push((key,Arc::new([key.as_slice(),b" retained"].concat())));}layer}
struct Fixture{directory:Directory,engine:Session,id:LayerId,other:LayerId,group:LayerId,raster:LayerId,path:PathBuf,bytes:Vec<u8>}
fn fixture(depth:u32,format:&str,linked:bool)->Fixture{
    let directory=directory();let path=directory.0.join(format!("source.{format}"));let bytes=encoded(format,rgba());std::fs::write(&path,&bytes).unwrap();let mut engine=Session::new();engine.execute("file.new",json!({"width":12,"height":10,"depth":depth})).unwrap();let fmt=engine.active().unwrap().doc.pixel_format();let first=object_layer("Original",if linked{SmartSource::Linked{path:path.to_string_lossy().into()}}else{SmartSource::Embedded{file_name:format!("source.{format}"),bytes:Arc::new(bytes.clone())}},2,1,fmt);let mut other=object_layer("Nested original",SmartSource::Embedded{file_name:format!("nested.{format}"),bytes:Arc::new(bytes.clone())},6,5,fmt);other.visible=false;let group=Layer::group("Hidden group",vec![other.clone()]);let group_id=group.id;let raster=Layer::raster("Excluded raster",fmt);let ids=[first.id,other.id,raster.id];
    engine.edit("Copy fixture",|doc,current|{doc.layers=vec![first,group,raster];*current=Some(ids[0]);let mut coverage=Surface::new(PixelFormat::GRAY8);coverage.fill_rect(Rect::from_xywh(3,2,2,3),&[0.5]);doc.selection=Some(coverage.clone());doc.channels.push(AlphaChannel::new("Retained alpha",coverage.clone()));doc.quick_mask=Some(AlphaChannel::new("Quick Mask",coverage));doc.metadata.psd_global_blocks.push((*b"8BIM",*b"zzzz",Arc::new(b"unrelated global metadata".to_vec())));doc.slices.list=vec![Slice{id:1,origin:SliceOrigin::Layer,layer:Some(ids[0]),rect:Rect::from_xywh(2,1,1,1),..Default::default()}];Ok(())}).unwrap();let index=engine.active_index().unwrap();engine.execute("document.activate",json!({"document":index})).unwrap();let state=engine.active_mut().unwrap();state.selected_layers=vec![ids[0],ids[1]];state.layer_anchor=Some(ids[1]);state.channel_view.target=photocraft_engine::channel_cmds::ChannelTarget::Alpha(0);engine.tools.foreground=[0.2,0.3,0.4,0.5];engine.tools.background=[0.7,0.6,0.5,0.4];let state=engine.active().unwrap();engine.edit_state.fade=Some(photocraft_engine::edit_menu_cmds::FadeSource{doc:state.doc.id,revision:state.revision,layer:ids[0],mask:false,label:"Older copy Fade".into()});Fixture{directory,engine,id:ids[0],other:ids[1],group:group_id,raster:ids[2],path,bytes}}
fn smart(doc:&Document,id:LayerId)->&SmartObject{let LayerContent::Smart(object)=&doc.layer(id).unwrap().content else{panic!("No Smart Object")};object}
fn twin(engine:&Session)->Session{let state=engine.active().unwrap();let mut copy=Session::new();copy.add_document(Document::new("Twin",state.doc.size,state.doc.mode,state.doc.depth),None);*copy.active_mut().unwrap()=state.clone();copy.journal=engine.journal.clone();copy.tools=engine.tools.clone();copy.presets=engine.presets.clone();copy.patterns=engine.patterns.clone();copy.clipboard=engine.clipboard.clone();copy.style_clipboard=engine.style_clipboard.clone();copy.edit_state=engine.edit_state.clone();super::super::super::color_views::Snapshot::capture(engine).unwrap().install(&mut copy).unwrap();copy}
fn mapped(id:LayerId,pairs:&[(LayerId,LayerId)])->LayerId{pairs.iter().find(|(native,_)|*native==id).map_or(id,|(_,actual)|*actual)}
fn normalized(doc:&Document,pairs:&[(LayerId,LayerId)])->Document{let mut doc=doc.clone();for (native,actual) in pairs{if let Some(layer)=doc.layer_mut(*native){layer.id=*actual;}}for slice in &mut doc.slices.list{slice.layer=slice.layer.map(|id|mapped(id,pairs));}doc}
fn same(actual:&Session,native:&Session,pairs:&[(LayerId,LayerId)]){
    let a=actual.active().unwrap();let n=native.active().unwrap();assert_eq!(*a.doc,normalized(&n.doc,pairs));assert_eq!(a.history.entries(),n.history.entries());assert_eq!(a.history.past_len(),n.history.past_len());for index in 0..a.history.past_len(){let a=a.history.state(index).unwrap();let n=n.history.state(index).unwrap();assert_eq!(*a,normalized(&n,pairs));}assert_eq!(a.history.redo_labels().collect::<Vec<_>>(),n.history.redo_labels().collect::<Vec<_>>());assert_eq!((a.revision,a.saved_revision,&a.coalesce,&a.path,&a.last_damage),(n.revision,n.saved_revision,&n.coalesce,&n.path,&n.last_damage));assert_eq!(a.active_layer,n.active_layer.map(|id|mapped(id,pairs)));assert_eq!(a.selected_layers,n.selected_layers.iter().map(|id|mapped(*id,pairs)).collect::<Vec<_>>());assert_eq!(a.layer_anchor,n.layer_anchor.map(|id|mapped(id,pairs)));assert_eq!(a.channel_view,n.channel_view);assert_eq!(a.isolated_layers,n.isolated_layers.iter().map(|id|mapped(*id,pairs)).collect::<Vec<_>>());assert_eq!(a.fx_collapsed,n.fx_collapsed.iter().map(|id|mapped(*id,pairs)).collect::<Vec<_>>());assert_eq!(format!("{:?}",a.symmetry_path),format!("{:?}",n.symmetry_path));assert_eq!(actual.journal,native.journal);assert_eq!(actual.edit_state.fade,native.edit_state.fade);assert_eq!(actual.tools.foreground,native.tools.foreground);assert_eq!(actual.tools.background,native.tools.background);assert_eq!(actual.tools.brush,native.tools.brush);assert_eq!(actual.style_clipboard,native.style_clipboard);assert_eq!(format!("{:?}",actual.clipboard),format!("{:?}",native.clipboard));assert_eq!(super::super::super::tools::presets(actual),super::super::super::tools::presets(native));assert_eq!(super::super::super::color_views::key(actual).unwrap(),super::super::super::color_views::key(native).unwrap());}
fn unchanged(engine:&Session,before:&Session){same(engine,before,&[]);assert!(Arc::ptr_eq(&engine.active().unwrap().doc,&before.active().unwrap().doc));}
fn host(engine:&mut Session,params:Value)->Result<Value,String>{super::super::super::execute_view_command(engine,COMMAND,params)}
fn checked(meta:&Metadata,object:&SmartObject)->Result<Option<super::super::Bytes>,String>{super::super::super::smart::source_bytes_checked(meta,&object.source,||Ok(()))}
fn copy_id(value:&Value)->LayerId{LayerId(value["layer"].as_u64().unwrap())}
fn differential(engine:&mut Session,native:&mut Session,params:Value,pairs:&mut Vec<(LayerId,LayerId)>)->LayerId{let actual=host(engine,params.clone()).unwrap();let expected=native.execute(COMMAND,params).unwrap();let id=copy_id(&actual);let native_id=copy_id(&expected);assert_ne!(id,native_id);assert_eq!(actual,json!({"layer":id.0}));assert_eq!(expected,json!({"layer":native_id.0}));pairs.push((native_id,id));same(engine,native,pairs);id}
fn cache_pixels(engine:&Session,id:LayerId,x0:i32,y0:i32){let doc=&engine.active().unwrap().doc;let cache=smart(doc,id).cache.as_ref().unwrap();let tolerance=match doc.depth{SampleType::U8=>1./255.,SampleType::U16=>2./65535.,SampleType::F32=>1e-6};for y in 0..10{for x in 0..12{let expected=if x==x0&&y==y0{[0.25,0.5,0.75,1.]}else{[0.;4]};let actual=cache.pixel(x,y);for channel in 0..4{assert!((actual[channel]-expected[channel]).abs()<=tolerance,"{:?}/{x},{y}/{channel}:{} != {}",doc.depth,actual[channel],expected[channel]);}assert_eq!(actual[3],expected[3]);}}}
fn assert_copy(engine:&Session,original:&Document,source_id:LayerId,id:LayerId,expected:Option<(&str,&[u8])>){let doc=&engine.active().unwrap().doc;let original_layer=original.layer(source_id).unwrap();assert_eq!(doc.layer(source_id),Some(original_layer));let copy=doc.layer(id).unwrap();assert_ne!(id,source_id);assert_eq!(copy.name,format!("{} copy",original_layer.name));assert_eq!(copy.psd_id,None);let mut retained=copy.clone();retained.id=source_id;retained.name=original_layer.name.clone();retained.psd_id=original_layer.psd_id;retained.psd_blocks=original_layer.psd_blocks.clone();let LayerContent::Smart(object)=&mut retained.content else{unreachable!()};object.source=smart(original,source_id).source.clone();object.psd_raw=smart(original,source_id).psd_raw.clone();assert_eq!(&retained,original_layer);assert_eq!(copy.psd_blocks,vec![(*b"zzzz",Arc::new(b"zzzz retained".to_vec()))]);assert!(smart(doc,id).psd_raw.is_none());if let Some((name,bytes))=expected{let SmartSource::Embedded{file_name,bytes:actual}=&smart(doc,id).source else{panic!("Copy is not embedded")};assert_eq!(file_name,name);assert_eq!(actual.as_slice(),bytes);}else{assert_eq!(smart(doc,id).source,smart(original,source_id).source);}assert_eq!(doc.metadata,original.metadata);assert_eq!(doc.selection,original.selection);assert_eq!(doc.channels,original.channels);assert_eq!(doc.quick_mask,original.quick_mask);}

#[test]
fn linked_copy_four_formats_three_depths_raw_source_and_cache_match_native_with_only_new_ids_normalized(){
    for linked in [false,true]{for depth in [8,16,32]{for format in ["png","psd","psb","pcraft"]{let mut f=fixture(depth,format,linked);let before=f.engine.active().unwrap().doc.clone();let past=f.engine.active().unwrap().history.past_len();let journal=f.engine.journal.len();let mut native=twin(&f.engine);let mut pairs=Vec::new();let id=differential(&mut f.engine,&mut native,json!({"layer":f.id.0,"vendor":[null,5]}),&mut pairs);assert_copy(&f.engine,&before,f.id,id,Some((&format!("source.{format}"),&f.bytes)));cache_pixels(&f.engine,id,2,1);cache_pixels(&f.engine,f.id,2,1);assert_eq!(f.engine.active().unwrap().history.past_len(),past+1);assert_eq!(f.engine.active().unwrap().history.undo_label(),Some(LABEL));assert_eq!(f.engine.journal.len(),journal+1);assert_eq!(f.engine.active().unwrap().doc.layers[1].id,id);
        if !linked{let SmartSource::Embedded{bytes:old,..}=&smart(&before,f.id).source else{unreachable!()};let SmartSource::Embedded{bytes:copy,..}=&smart(&f.engine.active().unwrap().doc,id).source else{unreachable!()};let SmartSource::Embedded{bytes:original,..}=&smart(&f.engine.active().unwrap().doc,f.id).source else{unreachable!()};assert!(Arc::ptr_eq(old,original));assert!(Arc::ptr_eq(old,copy));}
        let after=f.engine.active().unwrap().doc.clone();f.engine.execute("edit.undo",json!({})).unwrap();native.execute("edit.undo",json!({})).unwrap();same(&f.engine,&native,&pairs);assert!(Arc::ptr_eq(&f.engine.active().unwrap().doc,&before));f.engine.execute("edit.redo",json!({})).unwrap();native.execute("edit.redo",json!({})).unwrap();same(&f.engine,&native,&pairs);assert_eq!(f.engine.active().unwrap().doc,after);
    }}}
}

#[test]
fn linked_copy_unknown_disabled_corrupt_and_empty_sources_copy_raw_without_filter_admission_or_decode(){
    for disabled in [false,true]{for bytes in [Vec::new(),b"invalid original opaque bytes".to_vec()]{let mut f=fixture(16,"png",false);let id=f.id;let source=Arc::new(bytes.clone());f.engine.edit("Opaque source",|doc,_|{let LayerContent::Smart(object)=&mut doc.layer_mut(id).unwrap().content else{unreachable!()};object.source=SmartSource::Embedded{file_name:"raw.unknown".into(),bytes:source.clone()};object.filters_enabled=!disabled;Ok(())}).unwrap();let before=f.engine.active().unwrap().doc.clone();let count=photocraft_engine::smart_cmds::source_decode_count(&bytes,before.pixel_format());let mut native=twin(&f.engine);let mut pairs=Vec::new();let id=differential(&mut f.engine,&mut native,json!({}),&mut pairs);assert_copy(&f.engine,&before,f.id,id,Some(("raw.unknown",&bytes)));cache_pixels(&f.engine,id,2,1);assert_eq!(photocraft_engine::smart_cmds::source_decode_count(&bytes,before.pixel_format()),count);let SmartSource::Embedded{bytes,..}=&smart(&f.engine.active().unwrap().doc,id).source else{unreachable!()};assert!(Arc::ptr_eq(bytes,&source));}}
}

#[test]
fn linked_copy_missing_linked_source_is_success_retaining_reference_cache_and_unknown_filters(){
    let mut f=fixture(16,"png",true);std::fs::remove_file(&f.path).unwrap();let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let result=run_with(&mut f.engine,&json!({}),f.id,|meta,object|super::super::super::smart::source_bytes_checked(meta,&object.source,||panic!("unavailable raw copy cannot admit filters"))).unwrap();let id=copy_id(&result);let expected=native.execute(COMMAND,json!({})).unwrap();let pairs=[(copy_id(&expected),id)];same(&f.engine,&native,&pairs);assert_copy(&f.engine,&before,f.id,id,None);cache_pixels(&f.engine,id,2,1);
}

#[test]
fn linked_copy_metadata_first_authority_changes_only_copy_source_and_never_renders_it(){
    use photocraft_io::linked::{encode_linked_file,LinkedFile};let mut f=fixture(16,"png",true);let blue=encoded("png",[0,0,255,255].repeat(4));let mut block=encode_linked_file(&LinkedFile{uuid:f.path.to_string_lossy().into(),file_name:"metadata.png".into(),bytes:blue.clone()});block.extend(encode_linked_file(&LinkedFile{uuid:f.path.to_string_lossy().into(),file_name:"later.png".into(),bytes:encoded("png",rgba())}));f.engine.edit("Metadata copy source",|doc,_|{doc.metadata.psd_global_blocks.push((*b"8BIM",*b"lnk2",Arc::new(block)));Ok(())}).unwrap();std::fs::write(&f.path,b"disk must not decode").unwrap();let before=f.engine.active().unwrap().doc.clone();let count=photocraft_engine::smart_cmds::source_decode_count(&blue,before.pixel_format());let mut native=twin(&f.engine);let mut pairs=Vec::new();let id=differential(&mut f.engine,&mut native,json!({}),&mut pairs);assert_copy(&f.engine,&before,f.id,id,Some(("metadata.png",&blue)));cache_pixels(&f.engine,id,2,1);assert_eq!(photocraft_engine::smart_cmds::source_decode_count(&blue,before.pixel_format()),count);
}

#[test]
fn linked_copy_one_source_read_survives_donor_deletion_and_final_copy_owns_the_resolved_pin(){
    let mut f=fixture(16,"png",true);let before=f.engine.active().unwrap().doc.clone();let mut reads=0;let mut weak=None;let result=run_with(&mut f.engine,&json!({}),f.id,|meta,object|{reads+=1;let bytes=checked(meta,object)?;weak=bytes.as_ref().map(|(_,bytes)|Arc::downgrade(bytes));std::fs::remove_file(&f.path).unwrap();Ok(bytes)}).unwrap();let id=copy_id(&result);assert_eq!(reads,1);assert_copy(&f.engine,&before,f.id,id,Some(("source.png",&f.bytes)));cache_pixels(&f.engine,id,2,1);let retained=weak.unwrap().upgrade().unwrap();let SmartSource::Embedded{bytes,..}=&smart(&f.engine.active().unwrap().doc,id).source else{unreachable!()};assert!(Arc::ptr_eq(bytes,&retained));assert!(!f.path.exists());
}

#[test]
fn linked_copy_sparse_oversize_growing_and_reader_panic_refuse_without_owner_changes(){
    for failure in ["oversize","growing","panic"]{let mut f=fixture(16,"png",true);if failure=="oversize"{std::fs::OpenOptions::new().write(true).open(&f.path).unwrap().set_len(super::super::super::MAX_INPUT_BYTES+1).unwrap();}let before=twin(&f.engine);let error=match failure{"oversize"=>host(&mut f.engine,json!({})).unwrap_err(),"panic"=>run_with(&mut f.engine,&json!({}),f.id,|_,_|panic!("injected raw copy reader panic")).unwrap_err(),_=>{struct Growing{read:usize,max:usize}impl Read for Growing{fn read(&mut self,out:&mut[u8])->std::io::Result<usize>{self.max=self.max.max(out.len());out.fill(0x7a);self.read+=out.len();Ok(out.len())}}let mut reader=Growing{read:0,max:0};let error=run_with(&mut f.engine,&json!({}),f.id,|_,_|super::super::super::smart::replay_read_with_limit(&mut reader,32).map(|bytes|Some(("growing.png".into(),Arc::new(bytes))))).unwrap_err();assert_eq!(reader.read,33);assert!(reader.max<=64*1024);error}};if failure=="panic"{assert!(error.contains(COMMAND));assert!(error.contains("internal error"));}else{assert!(error.contains("512MB"));}unchanged(&f.engine,&before);}
}

#[test]
fn linked_copy_inactive_nested_source_stays_in_same_parent_and_original_layer_is_untouched(){
    let mut f=fixture(8,"png",false);let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let mut pairs=Vec::new();let id=differential(&mut f.engine,&mut native,json!({"layer":f.other.0,"target":"quickMask"}),&mut pairs);assert_copy(&f.engine,&before,f.other,id,Some(("nested.png",&f.bytes)));let children=f.engine.active().unwrap().doc.layer(f.group).unwrap().children().unwrap();assert_eq!(children.iter().map(|layer|layer.id).collect::<Vec<_>>(),vec![f.other,id]);assert_eq!(f.engine.active().unwrap().doc.layer(f.id),before.layer(f.id));cache_pixels(&f.engine,id,6,5);
}

#[test]
fn linked_copy_channel_masks_and_stale_layer_slice_posthooks_match_native_without_pixel_changes(){
    for context in ["alpha","quickMask","mask","staleSlices"]{let mut f=fixture(16,"png",false);match context{"quickMask"=>f.engine.active_mut().unwrap().channel_view.target=photocraft_engine::channel_cmds::ChannelTarget::Composite,"mask"=>{f.engine.execute("view.layerMask",json!({"mode":"gray"})).unwrap();},"staleSlices"=>{f.engine.edit("Stale slice",|doc,_|{doc.slices.list[0].rect=Rect::from_xywh(99,99,1,1);doc.slices.list.push(Slice{id:2,origin:SliceOrigin::Layer,layer:Some(LayerId(u64::MAX)),..Default::default()});Ok(())}).unwrap();},_=>{}}let before=f.engine.active().unwrap().doc.clone();let mut native=twin(&f.engine);let mut pairs=Vec::new();let id=differential(&mut f.engine,&mut native,json!({"target":"pixels"}),&mut pairs);assert_copy(&f.engine,&before,f.id,id,Some(("source.png",&f.bytes)));cache_pixels(&f.engine,id,2,1);assert_eq!(f.engine.active().unwrap().doc.slices.list.len(),1);assert_eq!(f.engine.active().unwrap().doc.slices.list[0].rect,Rect::new(2,1,3,2));}
}

#[test]
fn linked_copy_repeated_coalesced_explicit_source_uses_fresh_ids_one_history_and_older_fade(){
    let mut f=fixture(32,"png",false);let before=f.engine.active().unwrap().doc.clone();let fade=f.engine.edit_state.fade.clone();let past=f.engine.active().unwrap().history.past_len();let journal=f.engine.journal.len();let mut native=twin(&f.engine);let mut pairs=Vec::new();let mut ids=Vec::new();for _ in 0..3{let id=differential(&mut f.engine,&mut native,json!({"layer":f.id.0,"coalesce":"raw-copy"}),&mut pairs);assert_copy(&f.engine,&before,f.id,id,Some(("source.png",&f.bytes)));ids.push(id);assert_eq!(f.engine.edit_state.fade,fade);}assert_ne!(ids[0],ids[1]);assert_ne!(ids[1],ids[2]);assert_eq!(f.engine.active().unwrap().history.past_len(),past+1);assert_eq!(f.engine.active().unwrap().history.undo_label(),Some(LABEL));assert_eq!(f.engine.journal.len(),journal+3);let after=f.engine.active().unwrap().doc.clone();f.engine.execute("edit.undo",json!({})).unwrap();native.execute("edit.undo",json!({})).unwrap();same(&f.engine,&native,&pairs);assert!(Arc::ptr_eq(&f.engine.active().unwrap().doc,&before));f.engine.execute("edit.redo",json!({})).unwrap();native.execute("edit.redo",json!({})).unwrap();same(&f.engine,&native,&pairs);assert_eq!(f.engine.active().unwrap().doc,after);
}

#[test]
fn linked_copy_real_pending_preset_store_flushes_only_after_success_like_native(){
    use photocraft_engine::preset_store::{open,MemBackend};let mut f=fixture(16,"png",true);let mut native=twin(&f.engine);let actual=MemBackend::default();let expected=MemBackend::default();f.engine.attach_preset_store(open(Box::new(actual.clone())));native.attach_preset_store(open(Box::new(expected.clone())));for owner in [&mut f.engine,&mut native]{let mut preset=owner.tools.presets[0].clone();preset.name="Pending raw copy brush".into();preset.group="Raw copy owner".into();preset.builtin=false;owner.tools.presets.push(preset);owner.brush_presets_changed();}let files=actual.files.lock().unwrap().clone();let before=twin(&f.engine);assert!(run_with(&mut f.engine,&json!({}),f.id,|_,_|Err("injected source refusal".into())).is_err());unchanged(&f.engine,&before);assert_eq!(*actual.files.lock().unwrap(),files);let mut pairs=Vec::new();let id=differential(&mut f.engine,&mut native,json!({}),&mut pairs);cache_pixels(&f.engine,id,2,1);let after=actual.files.lock().unwrap().clone();assert_ne!(after,files);assert_eq!(after,*expected.files.lock().unwrap());assert!(open(Box::new(actual)).presets.iter().any(|preset|preset.name=="Pending raw copy brush"));
}

#[test]
fn linked_copy_actual_host_publication_reopens_immutable_original_and_copy_with_undo_redo(){
    let mut f=fixture(16,"psb",true);f.engine.active_mut().unwrap().channel_view.target=photocraft_engine::channel_cmds::ChannelTarget::Color(1);let before=f.engine.active().unwrap().doc.clone();let labels=f.engine.active().unwrap().history.entries();let id=copy_id(&host(&mut f.engine,json!({})).unwrap());let after=f.engine.active().unwrap().doc.clone();let mut session=super::super::super::PhotoSession{engine:f.engine,color_settings:None,version:String::new(),original_path:None,writer:Default::default()};let photo=ulid::Ulid::new().to_string();super::super::super::publish(&f.directory.0,&photo,&mut session).unwrap();let saved=f.directory.0.join(format!("{}.pcraft",session.version));let immutable=super::super::super::bundle::portable_bytes(&saved,super::super::super::MAX_INPUT_BYTES as usize).unwrap();std::fs::remove_file(&f.path).unwrap();session.engine.execute("edit.undo",json!({})).unwrap();super::super::super::publish(&f.directory.0,&photo,&mut session).unwrap();super::super::super::save_view(&f.directory.0,&session).unwrap();let mut reopened=super::super::super::restore_with_settings(&f.directory.0,&session.version,None,false).unwrap();let state=reopened.engine.active().unwrap();assert_eq!(state.doc,before);assert_eq!(state.history.entries(),labels);assert!(state.history.can_redo());assert_eq!(state.channel_view.target,photocraft_engine::channel_cmds::ChannelTarget::Color(1));reopened.engine.execute("edit.redo",json!({})).unwrap();assert_eq!(reopened.engine.active().unwrap().doc,after);assert_copy(&reopened.engine,&before,f.id,id,Some(("source.psb",&f.bytes)));cache_pixels(&reopened.engine,id,2,1);reopened.engine.execute("edit.undo",json!({})).unwrap();assert_eq!(reopened.engine.active().unwrap().doc,before);assert_eq!(immutable,super::super::super::bundle::portable_bytes(&saved,super::super::super::MAX_INPUT_BYTES as usize).unwrap());
}

#[test]
fn linked_copy_native_default_target_errors_parameters_and_active_job_precede_source_read(){
    for mode in ["default","null","nullLayer","stringLayer","negativeLayer","fractionalLayer","stale","raster","activeRaster","noActive","array","string","number"]{let mut f=fixture(8,"png",true);let params=match mode{"default"=>json!({}),"null"=>Value::Null,"nullLayer"=>json!({"layer":null}),"stringLayer"=>json!({"layer":"bad"}),"negativeLayer"=>json!({"layer":-1}),"fractionalLayer"=>json!({"layer":1.5}),"stale"=>json!({"layer":u64::MAX}),"raster"=>json!({"layer":f.raster.0}),"activeRaster"=>{f.engine.select_layer(f.raster).unwrap();json!({"layer":f.other.0})},"noActive"=>{f.engine.active_mut().unwrap().active_layer=None;json!({"layer":f.other.0})},"array"=>json!([]),"string"=>json!("invalid"),_=>json!(42)};let successful=matches!(mode,"default"|"null"|"nullLayer"|"stringLayer"|"negativeLayer"|"fractionalLayer");let before=twin(&f.engine);let mut native=twin(&f.engine);if successful{let mut pairs=Vec::new();differential(&mut f.engine,&mut native,params,&mut pairs);}else{std::fs::remove_file(&f.path).unwrap();let expected=native.execute(COMMAND,params.clone()).unwrap_err().to_string();assert_eq!(host(&mut f.engine,params.clone()).unwrap_err(),expected);if matches!(mode,"stale"|"raster"){let target=LayerId(params["layer"].as_u64().unwrap());let mut reads=0;assert_eq!(run_with(&mut f.engine,&params,target,|_,_|{reads+=1;panic!("invalid target must precede source read")}).unwrap_err(),expected);assert_eq!(reads,0);}unchanged(&f.engine,&before);}}
    let mut empty=Session::new();assert_eq!(host(&mut empty,json!({})).unwrap_err(),empty.execute(COMMAND,json!({})).unwrap_err().to_string());let mut f=fixture(8,"png",true);let release=Arc::new(AtomicBool::new(false));let worker=release.clone();struct Release(Arc<AtomicBool>);impl Drop for Release{fn drop(&mut self){self.0.store(true,Ordering::Relaxed);}}let _release=Release(release.clone());let started=f.engine.start_job("raw-copy-test",json!({}),"Retained raw copy job",true,move|context|{while !worker.load(Ordering::Relaxed){context.check()?;std::thread::yield_now();}Ok(())},|_,_|Ok(Value::Null)).unwrap();let photocraft_engine::jobs::Started::Job(job)=started else{panic!("Expected native job")};let before=twin(&f.engine);std::fs::remove_file(&f.path).unwrap();let error=host(&mut f.engine,json!({})).unwrap_err();assert_eq!(error,f.engine.execute(COMMAND,json!({})).unwrap_err().to_string());assert!(error.contains("Retained raw copy job"));unchanged(&f.engine,&before);release.store(true,Ordering::Relaxed);f.engine.wait_job(job).unwrap();
}
